# Fixes review token insert to match the review_tokens table's actual
# pre-existing schema (customer_email, customer_name, used, expires_at)
# instead of the schema originally designed from scratch.
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) "src\app\api\webhooks\stripe\route.ts"), $bytes)
Write-Host "UPDATED: src\app\api\webhooks\stripe\route.ts" -ForegroundColor Green
Write-Host "Now run: npx tsc --noEmit" -ForegroundColor Cyan